# ---------------------------------------------------------------- TVE (octubre de 2024): pieza entera del informativo, con Óscar Sánchez
LOC = {"enc": [316, 30, 648]}
E_L1 = (0.40, 23.10, "locucion", "Es la imagen del caos ayer por la mañana en el aeropuerto de Loiu: 8.000 personas en tierra porque sus vuelos habían sido cancelados o desviados por el huracán Kirk. Y aunque es una circunstancia extraordinaria, tienen derecho a que la compañía les reembolse el precio del billete o les coloque en otro vuelo cuanto antes, a que les busque alojamiento y a recibir el dinero gastado en desplazamientos y comida.", LOC)
E_O1 = (23.20, 50.10, "oscar", "No todo el mundo ha tenido la respuesta que se debería esperar de las compañías, ¿no? Bueno, por ahí seguramente habrá reclamaciones a las compañías para solicitar las indemnizaciones que corresponden por ley. A veces nos hemos encontrado situaciones en las que es muy complicado para el pasajero entender cuáles son sus derechos; la compañía muchas veces no ayuda en ello. Y luego también nos hemos encontrado que hay veces que las compañías no facilitan ni siquiera dónde se puede reclamar.", {"enc": [[23.2, 316, 30, 648], [24.84, 141, 31, 516], [34.96, 316, 30, 648], [46.76, 119, 29, 516]]})
E_L2 = (50.20, 65.05, "locucion", "El consejo de este despacho especializado en reclamaciones es guardar toda la documentación relacionada con el viaje, desde las comunicaciones con la compañía aérea a la tarjeta de embarque o el tique de la cafetería. Habrá que aportarla cuando se presente la reclamación.", LOC)
E_O2 = (65.15, 78.90, "oscar", "No es obligatoria la reclamación al momento; eso es importante que la gente lo tenga en cuenta. Se puede reclamar más adelante, hay tiempo para hacerlo. Lo importante, sobre todo, es en ese momento solucionar tu situación personal, es decir, dar solución al problema que estás teniendo.", {"enc": [[65.15, 316, 30, 648], [70.56, 134, 37, 510]]})
E_L3 = (79.30, 89.30, "locucion", "En casos como el de ayer se compensan únicamente los derechos previstos en la ley, y no aspectos como el tiempo perdido hasta embarcar en otro avión.", LOC)
# ---------------------------------------------------------------- TVE (enero de 2024): pieza entera del informativo, con Jon Ortiz
R_L1 = (2.20, 15.70, "locucion", "Retrasos, cancelaciones y tardanza en la entrega de equipaje o su pérdida. Las personas afectadas por la huelga del servicio de tierra de Iberia pueden reclamar los gastos derivados, desde el alquiler de un coche hasta un hotel o un abrigo.", LOC)
R_J1 = (15.88, 38.12, "jon", "…que es un motivo propio de la compañía. Podemos reclamar todos los gastos que nos ha supuesto la pérdida del avión: el reembolso o el vuelo que he tenido que comprar para volver a mi destino, o el hotel que he tenido que pagar para alojarme porque me he quedado tirado en cierto sitio, la comida que he tenido que pagar durante esos días; es decir, todos los gastos de asistencia mínimos, que se llaman. Pero, por otra parte, se genera el derecho a la indemnización.", {"enc": [[15.88, 280, 42, 532], [27.52, 316, 30, 648]]})
R_L2 = (38.37, 42.00, "locucion", "Este paisaje de maletas solitarias tiene muchas historias detrás.", LOC)
