R_L3 = (64.49, 69.78, "locucion", "¿Y si en esa maleta iba una herramienta de trabajo? ¿Y si he perdido dinero por ese retraso en su entrega?", LOC)
R_J3 = (70.05, 77.83, "jon", "Todo lo que se pueda acreditar y tenga cierta lógica: los gastos que has tenido, el dinero que has perdido y luego la molestia que te ha supuesto.")
